// Parse structured AI output and extract business signals
const input = $input.first()?.json || {};
let raw = input.output || input.text || input.content || '';
if (typeof raw !== 'string') raw = JSON.stringify(raw);

let parsed = null;
try {
  const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { reply: String(raw), facts_extracted: [], intent: 'general_inquiry', lead_stage: 'new', sentiment: 'neutral', escalate: false, escalation_reason: '' };
}

const reply = typeof parsed.reply === 'string' ? parsed.reply : String(raw);
const facts = Array.isArray(parsed.facts_extracted) ? parsed.facts_extracted : [];
const intent = typeof parsed.intent === 'string' ? parsed.intent : 'general_inquiry';
const leadStage = typeof parsed.lead_stage === 'string' ? parsed.lead_stage : 'new';
const sentiment = typeof parsed.sentiment === 'string' ? parsed.sentiment : 'neutral';
const escalate = !!parsed.escalate;
const escalationReason = typeof parsed.escalation_reason === 'string' ? parsed.escalation_reason : '';

const conversationId = $('When Executed by Another Workflow').first()?.json?.conversation_id || '';
const contactId = $('When Executed by Another Workflow').first()?.json?.contact_id || '';

return [{
  json: {
    reply,
    facts_extracted: facts,
    intent,
    lead_stage: leadStage,
    sentiment,
    escalate,
    escalation_reason: escalationReason,
    conversation_id: conversationId,
    contact_id: contactId,
  }
}];

try { const ctx = $input.first()?.json || {}; const facts = Array.isArray(ctx.customer_facts) ? ctx.customer_facts.filter(f => f && f.fact_key && f.fact_value !== null && f.fact_value !== undefined && f.fact_key !== 'null') : []; const factName = facts.find(f => f.fact_key === 'customer_name')?.fact_value || ''; const businessName = ctx.business_name || 'our company'; const customerName = (ctx.customer?.name && ctx.customer.name !== 'Unknown' ? ctx.customer.name : factName) || 'Unknown'; let prompt = `AUTHORITATIVE BUSINESS IDENTITY: ${businessName}
Never output unresolved template expressions such as {{ $json.business_name }}. If asked whether this is Garco, answer using the business identity above.
`; if (customerName !== 'Unknown') prompt += `AUTHORITATIVE CUSTOMER NAME: ${customerName}
If asked the customer name, answer it directly.
`; if (ctx.customer?.phone) prompt += `CUSTOMER PHONE: ${ctx.customer.phone}
`; if (facts.length) { prompt += '
CUSTOMER FACTS:
'; for (const f of facts) prompt += `- ${f.fact_key}: ${f.fact_value}
`; } if (Array.isArray(ctx.knowledge) && ctx.knowledge.length) { prompt += '
AUTHORITATIVE KNOWLEDGE:
'; for (const kb of ctx.knowledge.slice(0, 8)) prompt += `- ${kb.chunk_text}
`; } if (Array.isArray(ctx.products) && ctx.products.length) { prompt += '
PRODUCTS:
'; for (const p of ctx.products.slice(0, 20)) prompt += `- ${p.name}: ${p.price} ${p.currency}
`; } const recent = Array.isArray(ctx.recent_messages) ? ctx.recent_messages.slice(-6) : []; const history = recent.map(m => `${m.direction === 'in' || m.direction === 'incoming' ? 'Customer' : 'Assistant'}: ${m.text_body}`).join('
') || 'No previous messages.'; return [{ json: { formattedPrompt: prompt, business_name: businessName, conversationHistory: history, customerFacts: facts, customerName, currentMessage: ctx.current_message?.text || '' } }]; } catch(e) { return [{ json: { formattedPrompt: 'AUTHORITATIVE BUSINESS IDENTITY: our company
No context available.', business_name: 'our company', conversationHistory: 'No previous messages.', customerFacts: [], customerName: 'Unknown' } }]; }

