INSERT INTO messages (
    conversation_id, whatsapp_message_id, direction,
    sender_type, message_type, text_body, metadata
)
VALUES (
    $1, gen_random_uuid()::text, 'outgoing',
    'ai', 'text', $2, '{}'::jsonb
)
RETURNING id;

UPDATE conversations
SET last_message_at = NOW(), updated_at = NOW()
WHERE id = $1;
